 1→import { createHmac, timingSafeEqual } from "node:crypto";
 2→
 3→export const SIGNATURE_SCHEME = "v1";
 4→export const TOLERANCE_SECONDS = 300;
 5→
 6→export class WebhookVerificationError extends Error {
 7→  constructor(message: string, readonly code: string) {
 8→    super(message);
 9→    this.name = "WebhookVerificationError";
10→  }
11→}
12→
13→export interface VerifyOptions {
14→  /** Unix seconds; defaults to wall clock. */
15→  now?: number;
16→}
17→
18→interface ParsedHeader {
19→  timestamp: number;
20→  signatures: string[];
21→}
22→
23→function parseSignatureHeader(header: string): ParsedHeader {
24→  const parts = header.split(",").map((p) => p.trim());
25→  let timestamp = NaN;
26→  const signatures: string[] = [];
27→  for (const part of parts) {
28→    const [key, value] = part.split("=");
29→    if (key === "t") timestamp = Number(value);
30→    if (key === SIGNATURE_SCHEME) signatures.push(value);
31→  }
32→  if (!Number.isFinite(timestamp) || signatures.length === 0) {
33→    throw new WebhookVerificationError("malformed signature header", "malformed_header");
34→  }
35→  return { timestamp, signatures };
36→}
37→
38→export function verifySignature(rawBody: string, header: string, secret: string, opts: VerifyOptions = {}): ParsedHeader {
39→  const { timestamp, signatures } = parseSignatureHeader(header);
40→  // TODO(expiry): tolerance is parsed but never enforced - see tests/webhook.test.ts
41→  const expected = createHmac("sha256", secret).update(`${timestamp}.${rawBody}`).digest("hex");
42→  const match = signatures.some((sig) => safeEqual(sig, expected));
43→  if (!match) {
44→    throw new WebhookVerificationError("signature mismatch", "signature_mismatch");
45→  }
46→  return { timestamp, signatures };
47→}
48→
49→function safeEqual(a: string, b: string): boolean {
50→  const ab = Buffer.from(a, "utf8");
51→  const bb = Buffer.from(b, "utf8");
52→  return ab.length === bb.length && timingSafeEqual(ab, bb);
53→}

